screenPanels.initJs:
function(container, apiUrl, tables) {
  // データ取得と初期化
  async function initDashboard() {
    try {
      const projects = await window.aivicApi.list(0) || tables[0]?.records || [];

      // KPI計算
      const total = projects.length;
      const active = projects.filter(p => p.status === '進行中' || p.status === '開発中').length;
      const completed = projects.filter(p => p.status === '完了' || p.status === 'リリース済み').length;
      const pending = projects.filter(p => p.priority === '高' && p.status !== '完了').length;

      // KPI表示更新
      container.querySelector('#kpi-total').textContent = total;
      container.querySelector('#kpi-active').textContent = active;
      container.querySelector('#kpi-completed').textContent = completed;
      container.querySelector('#kpi-pending').textContent = pending;

      // 要対応項目の表示
      renderUrgentItems(projects);

      // 最新更新の表示
      renderRecentUpdates(projects);

      // チャート描画
      renderProgressChart(projects);
      renderStatusChart(projects);

    } catch (error) {
      console.error('Dashboard initialization failed:', error);
    }
  }

  // 要対応項目の描画
  function renderUrgentItems(projects) {
    const urgentItems = projects
      .filter(p => p.priority === '高' && p.status !== '完了')
      .slice(0, 5);

    const html = urgentItems.length > 0 ? urgentItems.map(item => `
      <div style="padding: 8px 0; border-bottom: 1px solid var(--border); cursor: pointer;" onclick="window.showScreen('scr-3')">
        <div style="font-size: 14px; font-weight: 500; color: var(--text); margin-bottom: 2px;">${item.name || 'プロジェクト'}</div>
        <div style="font-size: 12px; color: var(--text-muted);">
          <span style="color: #f59e0b;">●</span> ${item.status || '未設定'} | ${item.assignee || '未割当'}
        </div>
      </div>
    `).join('') : '<div style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 14px;">要対応項目はありません</div>';

    container.querySelector('#urgent-items').innerHTML = html;
  }

  // 最新更新の描画
  function renderRecentUpdates(projects) {
    const recentProjects = projects
      .sort((a, b) => new Date(b.updated_at || b.created_at || '2024-01-01') - new Date(a.updated_at || a.created_at || '2024-01-01'))
      .slice(0, 4);

    const html = recentProjects.map(item => `
      <div style="padding: 8px 0; border-bottom: 1px solid var(--border); cursor: pointer;" onclick="window.showScreen('scr-3')">
        <div style="font-size: 14px; font-weight: 500; color: var(--text); margin-bottom: 2px;">${item.name || 'プロジェクト'}</div>
        <div style="font-size: 12px; color: var(--text-muted);">
          ${new Date(item.updated_at || item.created_at || '2024-01-01').toLocaleDateString('ja-JP')} | ${item.status || '未設定'}
        </div>
      </div>
    `).join('');

    container.querySelector('#recent-updates').innerHTML = html;
  }

  // 進捗チャート描画
  function renderProgressChart(projects) {
    const ctx = container.querySelector('#progress-chart').getContext('2d');

    // 月別データ集計
    const monthlyData = {};
    projects.forEach(p => {
      const date = new Date(p.created_at || '2024-01-01');
      const monthKey = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
      monthlyData[monthKey] = (monthlyData[monthKey] || 0) + 1;
    });

    const sortedMonths = Object.keys(monthlyData).sort().slice(-6);
    const values = sortedMonths.map(month => monthlyData[month] || 0);

    new Chart(ctx, {
      type: 'line',
      data: {
        labels: sortedMonths.map(m => m.substring(5) + '月'),
        datasets: [{
          label: 'プロジェクト数',
          data: values,
          borderColor: '#3b82f6',
          backgroundColor: 'rgba(59, 130, 246, 0.1)',
          tension: 0.4,
          fill: true
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: false }
        },
        scales: {
          y: { beginAtZero: true }
        }
      }
    });
  }

  // ステータス分布チャート描画
  function renderStatusChart(projects) {
    const ctx = container.querySelector('#status-chart').getContext('2d');

    const statusCounts = {};
    projects.forEach(p => {
      const status = p.status || '未設定';
      statusCounts[status] = (statusCounts[status] || 0) + 1;
    });

    const labels = Object.keys(statusCounts);
    const data = Object.values(statusCounts);
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

    new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: labels,
        datasets: [{
          data: data,
          backgroundColor: colors.slice(0, labels.length),
          borderWidth: 0
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'bottom',
            labels: { padding: 15, usePointStyle: true }
          }
        }
      }
    });
  }

  // 初期化実行
  initDashboard();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#app-development-tbody');

  // ステータス別の色分け
  function getStatusBadge(status) {
    const statusColors = {
      '企画中': 'bg-blue-100 text-blue-800 border-blue-200',
      '開発中': 'bg-yellow-100 text-yellow-800 border-yellow-200',
      'テスト中': 'bg-purple-100 text-purple-800 border-purple-200',
      'リリース済み': 'bg-green-100 text-green-800 border-green-200',
      '保守中': 'bg-gray-100 text-gray-800 border-gray-200'
    };
    const colorClass = statusColors[status] || 'bg-gray-100 text-gray-800 border-gray-200';
    return `<span class="inline-block px-2 py-1 text-xs rounded border ${colorClass}">${status || '-'}</span>`;
  }

  // 進捗バー
  function getProgressBar(progress) {
    const percent = Math.min(100, Math.max(0, progress || 0));
    const color = percent >= 80 ? '#10b981' : percent >= 50 ? '#f59e0b' : '#ef4444';
    return `
      <div class="flex items-center gap-2">
        <div class="w-16 h-2 bg-rgba(255,255,255,0.1) rounded-full overflow-hidden">
          <div class="h-full transition-all" style="width: ${percent}%; background-color: ${color};"></div>
        </div>
        <span class="text-xs text-[var(--text-muted)]">${percent}%</span>
      </div>
    `;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(row => `
      <tr class="border-b border-[var(--border)] hover:bg-rgba(255,255,255,0.02) cursor-pointer" data-id="${row.id}">
        <td class="px-4 py-3">
          <div class="font-medium text-[var(--text)]">${row.app_name || '-'}</div>
          <div class="text-xs text-[var(--text-muted)]">${row.description || ''}</div>
        </td>
        <td class="px-4 py-3">${getStatusBadge(row.status)}</td>
        <td class="px-4 py-3 text-sm text-[var(--text)]">${row.platform || '-'}</td>
        <td class="px-4 py-3 text-sm text-[var(--text)]">${row.assignee || '-'}</td>
        <td class="px-4 py-3">${getProgressBar(row.progress)}</td>
        <td class="px-4 py-3 text-sm text-[var(--text)]">${row.start_date || '-'}</td>
        <td class="px-4 py-3 text-sm text-[var(--text)]">${row.end_date || '-'}</td>
        <td class="px-4 py-3">
          <div class="flex gap-1">
            <button class="action-btn secondary edit-btn text-xs px-2 py-1" data-id="${row.id}">編集</button>
            <button class="action-btn secondary delete-btn text-xs px-2 py-1" data-id="${row.id}">削除</button>
          </div>
        </td>
      </tr>
    `).join('');

    // 結果件数と統計を更新
    container.querySelector('#result-count').textContent = rows.length;
    updateStats(rows);
  }

  // 統計情報更新
  function updateStats(rows) {
    const total = rows.length;
    const developing = rows.filter(r => r.status === '開発中').length;
    const released = rows.filter(r => r.status === 'リリース済み').length;

    container.querySelector('#stat-total').textContent = total;
    container.querySelector('#stat-developing').textContent = developing;
    container.querySelector('#stat-released').textContent = released;
  }

  // 初期データ表示
  renderRows(tables[0]?.records || []);

  // 検索・フィルタ処理
  async function performSearch() {
    const appName = container.querySelector('#search-app-name').value.toLowerCase();
    const status = container.querySelector('#filter-status').value;
    const platform = container.querySelector('#filter-platform').value;
    const assignee = container.querySelector('#search-assignee').value.toLowerCase();
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    const allRows = await window.aivicApi.list(0);
    if (!allRows) return;

    let filteredRows = allRows.filter(row => {
      if (appName && !((row.app_name || '').toLowerCase().includes(appName))) return false;
      if (status && row.status !== status) return false;
      if (platform && row.platform !== platform) return false;
      if (assignee && !((row.assignee || '').toLowerCase().includes(assignee))) return false;
      if (startDate && row.start_date && row.start_date < startDate) return false;
      if (endDate && row.end_date && row.end_date > endDate) return false;
      return true;
    });

    // 並び替え適用
    const sortField = container.querySelector('#sort-field').value;
    const sortOrder = container.querySelector('#sort-order').value;

    filteredRows.sort((a, b) => {
      let aVal = a[sortField] || '';
      let bVal = b[sortField] || '';

      if (sortField === 'progress') {
        aVal = parseFloat(aVal) || 0;
        bVal = parseFloat(bVal) || 0;
      }

      if (aVal < bVal) return sortOrder === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortOrder === 'asc' ? 1 : -1;
      return 0;
    });

    renderRows(filteredRows);
  }

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', performSearch);

  // 並び替え変更時
  container.querySelector('#sort-field').addEventListener('change', performSearch);
  container.querySelector('#sort-order').addEventListener('change', performSearch);

  // リセットボタン
  container.querySelector('#btn-reset').addEventListener('click', async () => {
    container.querySelector('#search-app-name').value = '';
    container.querySelector('#filter-status').value = '';
    container.querySelector('#filter-platform').value = '';
    container.querySelector('#search-assignee').value = '';
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';

    const allRows = await window.aivicApi.list(0);
    if (allRows) renderRows(allRows);
  });

  // CSVエクスポート
  container.querySelector('#btn-csv-export').addEventListener('click', async () => {
    const allRows = await window.aivicApi.list(0);
    if (!allRows) return;

    const headers = ['アプリ名', 'ステータス', 'プラットフォーム', '担当者', '進捗率', '開始日', '予定終了日', '説明'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...allRows.map(row => [
        `"${(row.app_name || '').replace(/"/g, '""')}"`,
        `"${(row.status || '').replace(/"/g, '""')}"`,
        `"${(row.platform || '').replace(/"/g, '""')}"`,
        `"${(row.assignee || '').replace(/"/g, '""')}"`,
        row.progress || '0',
        row.start_date || '',
        row.end_date || '',
        `"${(row.description || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `app_development_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const editBtn = e.target.closest('.edit-btn');
    const deleteBtn = e.target.closest('.delete-btn');
    const row = e.target.closest('tr[data-id]');

    if (editBtn) {
      const id = editBtn.dataset.id;
      window.showScreen('scr-3', { editId: id });
    } else if (deleteBtn) {
      const id = deleteBtn.dataset.id;
      if (!confirm('このプロジェクトを削除しますか？')) return;

      await window.aivicApi.delete(0, id);
      const updatedRows = await window.aivicApi.list(0);
      if (updatedRows) renderRows(updatedRows);
    } else if (row && !e.target.closest('button')) {
      // 行クリックで詳細画面へ
      const id = row.dataset.id;
      window.showScreen('scr-3', { viewId: id });
    }
  });
}

function(container, apiUrl, tables) {
  let currentAppId = null;
  let currentTab = 'basic';

  // タブ切り替え機能
  function switchTab(tabId) {
    // 全タブコンテンツを非表示
    container.querySelectorAll('.tab-content').forEach(content => {
      content.classList.add('hidden');
    });

    // 全タブボタンの active 状態をリセット
    container.querySelectorAll('.tab-btn').forEach(btn => {
      btn.style.borderColor = 'transparent';
      btn.style.color = 'var(--text-muted)';
    });

    // 選択されたタブを表示
    const targetContent = container.querySelector(`#tab-${tabId}`);
    const targetBtn = container.querySelector(`[data-tab="${tabId}"]`);

    if (targetContent) {
      targetContent.classList.remove('hidden');
    }
    if (targetBtn) {
      targetBtn.style.borderColor = 'var(--primary)';
      targetBtn.style.color = 'var(--text)';
    }

    currentTab = tabId;
  }

  // アプリ一覧の再描画
  function renderAppList(apps) {
    const appList = container.querySelector('#app-list');
    if (!appList) return;

    appList.innerHTML = apps.map(app => `
      <div class="app-item p-2 rounded cursor-pointer border border-solid hover:bg-opacity-80" 
           style="background: rgba(0,0,0,0.15); border-color: rgba(255,255,255,0.08);" 
           data-id="${app.id || ''}">
        <div class="text-xs font-medium" style="color: var(--text);">${app.name || app.appName || 'アプリ名未設定'}</div>
        <div class="text-xs mt-1" style="color: var(--text-muted);">${app.status || app.appStatus || '未設定'}</div>
      </div>
    `).join('');
  }

  // アプリ詳細の表示
  function loadAppDetail(appId) {
    const apps = tables[0]?.records || [];
    const app = apps.find(a => a.id == appId);

    if (!app) return;

    currentAppId = appId;

    // タイトル更新
    const title = container.querySelector('#app-title');
    const subtitle = container.querySelector('#app-subtitle');
    if (title) title.textContent = app.name || app.appName || 'アプリ詳細';
    if (subtitle) subtitle.textContent = `ID: ${appId} | ${app.status || app.appStatus || '未設定'}`;

    // フォーム値設定
    const fields = {
      'app-name': app.name || app.appName || '',
      'app-status': app.status || app.appStatus || '',
      'developer': app.developer || '',
      'start-date': app.startDate || app.start_date || '',
      'description': app.description || '',
      'environment': app.environment || '',
      'deploy-date': app.deployDate || app.deploy_date || '',
      'app-url': app.url || app.appUrl || '',
      'deploy-notes': app.deployNotes || app.deploy_notes || ''
    };

    Object.entries(fields).forEach(([id, value]) => {
      const element = container.querySelector(`#${id}`);
      if (element) element.value = value;
    });

    // 機能チェックボックス
    const features = app.features ? app.features.split(',') : [];
    container.querySelector('#feature-auth').checked = features.includes('auth');
    container.querySelector('#feature-data').checked = features.includes('data');
    container.querySelector('#feature-notification').checked = features.includes('notification');
    container.querySelector('#feature-api').checked = features.includes('api');
  }

  // 初期データ表示
  if (tables[0]?.records) {
    renderAppList(tables[0].records);
  }

  // 最新データ取得
  window.aivicApi.list(0).then(apps => {
    if (apps) {
      renderAppList(apps);
    }
  });

  // 初期タブ設定
  switchTab('basic');

  // タブクリックイベント
  container.addEventListener('click', (e) => {
    const tabBtn = e.target.closest('.tab-btn');
    if (tabBtn) {
      const tabId = tabBtn.dataset.tab;
      switchTab(tabId);
    }
  });

  // アプリ選択イベント
  container.addEventListener('click', (e) => {
    const appItem = e.target.closest('.app-item');
    if (appItem) {
      const appId = appItem.dataset.id;
      if (appId) {
        loadAppDetail(appId);

        // 選択状態の更新
        container.querySelectorAll('.app-item').forEach(item => {
          item.style.background = 'rgba(0,0,0,0.15)';
        });
        appItem.style.background = 'rgba(var(--primary-rgb, 59, 130, 246), 0.15)';
      }
    }
  });

  // 保存ボタン
  container.querySelector('[data-testid="save-button"]').addEventListener('click', async () => {
    if (!currentAppId) {
      alert('アプリを選択してください');
      return;
    }

    const features = [];
    if (container.querySelector('#feature-auth').checked) features.push('auth');
    if (container.querySelector('#feature-data').checked) features.push('data');
    if (container.querySelector('#feature-notification').checked) features.push('notification');
    if (container.querySelector('#feature-api').checked) features.push('api');

    const updateData = {
      name: container.querySelector('#app-name').value,
      appName: container.querySelector('#app-name').value,
      status: container.querySelector('#app-status').value,
      appStatus: container.querySelector('#app-status').value,
      developer: container.querySelector('#developer').value,
      startDate: container.querySelector('#start-date').value,
      start_date: container.querySelector('#start-date').value,
      description: container.querySelector('#description').value,
      environment: container.querySelector('#environment').value,
      deployDate: container.querySelector('#deploy-date').value,
      deploy_date: container.querySelector('#deploy-date').value,
      url: container.querySelector('#app-url').value,
      appUrl: container.querySelector('#app-url').value,
      deployNotes: container.querySelector('#deploy-notes').value,
      deploy_notes: container.querySelector('#deploy-notes').value,
      features: features.join(',')
    };

    const result = await window.aivicApi.update(0, currentAppId, updateData);
    if (result) {
      alert('保存しました');
      // アプリ一覧を更新
      const apps = await window.aivicApi.list(0);
      if (apps) {
        renderAppList(apps);
      }
    }
  });

  // 新規作成ボタン
  container.querySelector('[data-testid="new-app-button"]').addEventListener('click', async () => {
    const newApp = {
      name: '新規アプリ',
      appName: '新規アプリ',
      status: 'planning',
      appStatus: 'planning',
      developer: '',
      startDate: new Date().toISOString().split('T')[0],
      start_date: new Date().toISOString().split('T')[0],
      description: '',
      environment: 'development',
      deployDate: '',
      deploy_date: '',
      url: '',
      appUrl: '',
      deployNotes: '',
      deploy_notes: '',
      features: ''
    };

    const result = await window.aivicApi.save(0, newApp);
    if (result) {
      // アプリ一覧を更新
      const apps = await window.aivicApi.list(0);
      if (apps) {
        renderAppList(apps);
        // 新規作成したアプリを選択
        if (result.id) {
          loadAppDetail(result.id);
        }
      }
    }
  });

  // キャンセルボタン
  container.querySelector('[data-testid="cancel-button"]').addEventListener('click', () => {
    if (currentAppId) {
      loadAppDetail(currentAppId);
    }
  });
}
